package com.bank.reporting;  // DIFFERENT package → same simple name coexists safely

import java.math.BigDecimal;

// A reporting summary that happens to also be called Account. Its fully qualified
// name com.bank.reporting.Account is distinct from com.bank.accounts.Account.
public class Account {
    private final String accountId;
    private final BigDecimal closingBalance;

    public Account(String accountId, BigDecimal closingBalance) {
        this.accountId = accountId;
        this.closingBalance = closingBalance;
    }

    public String getAccountId() { return accountId; }
    public BigDecimal getClosingBalance() { return closingBalance; }
}
