package com.bank.accounts;

import java.math.BigDecimal;

// Static imports: bring the rounding mode and max into scope so the fee formula
// reads like the business rule, without the Math. and RoundingMode. prefixes.
import static java.math.RoundingMode.HALF_EVEN;
import static java.lang.Math.max;

public class FeeCalculator {
    // Monthly maintenance fee = max(minimum fee, balance * rate), rounded to paise.
    public BigDecimal monthlyFee(BigDecimal balance, BigDecimal rate, BigDecimal minFee) {
        BigDecimal percentFee = balance.multiply(rate).setScale(2, HALF_EVEN);
        // max here is Math.max on the compared int of compareTo, kept simple for the demo
        BigDecimal chosen = (percentFee.compareTo(minFee) >= 0) ? percentFee : minFee;
        int tierBonus = max(0, chosen.compareTo(new BigDecimal("1000"))); // demo use of static max
        return chosen.add(new BigDecimal(tierBonus)).setScale(2, HALF_EVEN);
    }
}
