package com.bank.accounts;

import java.math.BigDecimal;
import java.util.logging.*;

// To use BOTH Account types we must disambiguate. We import the accounts one
// normally and refer to the reporting one by its fully qualified name. This is
// exactly the clash a wildcard import would have made ambiguous.
public class PackageImportDemo {
    private static final Logger log = Logger.getLogger(PackageImportDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setLevel(Level.ALL);
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        Account rajesh = new Account("SAV2001", "Rajesh Kumar", new BigDecimal("1000000"));
        Account priya  = new Account("CUR3001", "Priya Sharma", new BigDecimal("250000"));

        BigDecimal rentAmount = new BigDecimal("50000");
        rajesh.debit(rentAmount);
        priya.credit(rentAmount);
        log.info(() -> "Transfer " + rentAmount + " from " + rajesh.getAccountId()
                + " to " + priya.getAccountId() + " SUCCESS");
        log.info(() -> "Rajesh=" + rajesh.getBalance() + " Priya=" + priya.getBalance());

        // Static-import-powered fee formula for Priya's current account.
        FeeCalculator calc = new FeeCalculator();
        BigDecimal fee = calc.monthlyFee(priya.getBalance(),
                new BigDecimal("0.0005"), new BigDecimal("100.00"));
        log.info(() -> "Priya monthly maintenance fee: " + fee);

        // Same simple name 'Account' from a different package, fully qualified.
        com.bank.reporting.Account summary =
                new com.bank.reporting.Account(priya.getAccountId(), priya.getBalance());
        log.info(() -> "Reporting summary for " + summary.getAccountId()
                + " closing=" + summary.getClosingBalance());
    }
}
